using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Threading;using SlopProX;
internal static class BackendIntegrationTests
{
 static int Main(string[] args){string report=args[0];var lines=new List<string>();int failures=0;Action<string,Action> test=delegate(string name,Action body){try{body();lines.Add("PASS "+name);}catch(Exception ex){failures++;lines.Add("FAIL "+name+" :: "+ex);}};
 test("WASAPI real endpoint enumeration and event-driven virtual loopback at 48000 Hz",delegate{var outputs=WasapiStream.Devices(false);var inputs=WasapiStream.Devices(true);foreach(var d in outputs)lines.Add("OUTPUT "+d.Name+" :: "+d.Id);foreach(var d in inputs)lines.Add("INPUT "+d.Name+" :: "+d.Id);var output=outputs.FirstOrDefault(d=>d.Name.Contains("7/8")||d.Name.Contains("7-8"));var input=inputs.FirstOrDefault(d=>d.Name.Contains("Loopback")||d.Name.Contains("7/8"));if(output==null||input==null)throw new Exception("Minifuse virtual 7/8 endpoints not found.");long capture=0;float peak=0;using(var reader=new WasapiStream(input.Id,true,false,48000,512,delegate(float[] data,int frames,int channels,long pos){capture+=frames;for(int i=0;i<frames*channels;i++)peak=Math.Max(peak,Math.Abs(data[i]));}))using(var writer=new WasapiStream(output.Id,false,false,48000,512,delegate(float[] data,int frames,int channels,long pos){for(int i=0;i<frames;i++)data[i*2]=data[i*2+1]=(float)(.04*Math.Sin(2*Math.PI*440*(pos+i)/48000));})){Thread.Sleep(800);if(writer.FramesPlayed<10000||capture<10000||peak<.005)throw new Exception("Loopback failed: output="+writer.FramesPlayed+" capture="+capture+" peak="+peak);lines.Add("WASAPI loopback frames="+capture+" peak="+peak+" input channels="+reader.Channels);}});
 test("WASAPI sample-rate reconfiguration 44100 / 96000 Hz",delegate{foreach(int rate in new[]{44100,96000})using(var writer=new WasapiStream("",false,false,rate,256,delegate(float[] d,int n,int c,long p){})){Thread.Sleep(120);if(writer.FramesPlayed<=0)throw new Exception("No callbacks at "+rate);lines.Add("WASAPI active sample rate="+rate+" frames="+writer.FramesPlayed);}});
 test("WASAPI exclusive format negotiation and aligned full-buffer packets at 48000 / 44100 Hz",delegate{var output=WasapiStream.Devices(false).FirstOrDefault(d=>d.Name.Contains("7/8")||d.Name.Contains("7-8"));if(output==null)throw new Exception("Virtual output endpoint unavailable.");foreach(int rate in new[]{48000,44100})using(var stream=new WasapiStream(output.Id,false,true,rate,512,delegate(float[] data,int frames,int channels,long position){Array.Clear(data,0,frames*channels);})){Exception runtime=null;stream.Failed+=ex=>runtime=ex;Thread.Sleep(220);long frames=stream.FramesPlayed;if(runtime!=null)throw runtime;if(frames<1000)throw new Exception("Exclusive stream did not render callbacks.");lines.Add("EXCLUSIVE rate="+rate+" frames="+frames+" format="+stream.SampleFormat+" actual buffer="+stream.DeviceBufferFrames);}});
 var drivers=AsioDrivers.Enumerate();foreach(var d in drivers)lines.Add("ASIO "+d.Name+" :: "+d.Clsid);
 test("ASIO official SDK companion: real driver input/output callbacks, 48000 and 44100 Hz",delegate{var driver=drivers.FirstOrDefault(d=>d.Name.IndexOf("FL Studio",StringComparison.OrdinalIgnoreCase)>=0);if(driver==null)throw new Exception("FL Studio ASIO driver unavailable.");foreach(int rate in new[]{48000,44100,48000}){long capture=0;var settings=new AppSettings{AudioBackend="ASIO",AsioDriver=driver.Clsid,SampleRate=rate,BufferFrames=512};using(var stream=new AsioCompanion(settings,delegate(float[] data,int n,long p){Array.Clear(data,0,n*2);},delegate(float[] data,int n,int c,long p){capture+=n;})){Thread.Sleep(350);if(stream.FramesPlayed<=0||capture<=0)throw new Exception("No ASIO callbacks.");lines.Add("ASIO rate="+rate+" frames="+stream.FramesPlayed+" inputChannels="+stream.InputChannels+" inputLatency="+stream.InputLatency+" outputLatency="+stream.OutputLatency);}}});
 test("Ableton Link two independent GPL companions discover peers and synchronize tempo / start-stop",delegate{using(var one=new LinkCompanion())using(var two=new LinkCompanion()){one.Commit(123.5,true);DateTime end=DateTime.UtcNow.AddSeconds(5);while(DateTime.UtcNow<end&&(one.Peers<1||two.Peers<1||Math.Abs(two.Tempo-123.5)>.01))Thread.Sleep(50);if(one.Peers<1||two.Peers<1)throw new Exception("No local Link peers discovered.");one.Commit(127.25,true);end=DateTime.UtcNow.AddSeconds(3);while(DateTime.UtcNow<end&&Math.Abs(two.Tempo-127.25)>.01)Thread.Sleep(30);if(Math.Abs(two.Tempo-127.25)>.01)throw new Exception("Tempo did not synchronize.");lines.Add("LINK peers="+one.Peers+"/"+two.Peers+" tempo="+two.Tempo+" beat="+two.Beat+" playing="+two.Playing);}});
 lines.Add("NOT RUN physical microphone input, actual keyboard keypresses, speaker audition, external LAN peer, VRChat client.");File.WriteAllLines(report,lines);foreach(string l in lines)Console.WriteLine(l);return failures==0?0:1;}
}
